// Minimal Markdown parser (subset) - no external deps
const md = (() => {
  const escape = s => s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const inline = s => s
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    .replace(/~~([^~]+)~~/g, '<del>$1</del>')
    .replace(/---/g, '—')
    .replace(/\.\.\./g, '…')
    .replace(/--/g, '–');
  return text => {
    const lines = text.split('\n');
    const blocks = [];
    let current = [];
    let inCode = false;
    let codeLang = '';
    for (const line of lines) {
      if (line.startsWith('```')) {
        if (!inCode) { inCode = true; codeLang = line.slice(3).trim(); current = []; }
        else { inCode = false; blocks.push({type:'code', lang:codeLang, content:current.join('\n')}); current = []; }
      } else if (inCode) { current.push(line); }
      else if (line.match(/^#{1,3}\s/)) {
        const level = line.match(/^#+/).length;[0]
        blocks.push({type:'heading', level, content:inline(line.slice(level+1).trim())});
      } else if (line.startsWith('> ')) {
        blocks.push({type:'quote', content:inline(line.slice(2).trim())});
      } else if (line.match(/^[-*+]\s/)) {
        blocks.push({type:'li', content:inline(line.slice(2).trim())});
      } else if (line.match(/^\d+\.\s/)) {
        blocks.push({type:'li', ordered:true, content:inline(line.replace(/^\d+\.\s/,'').trim())});
      } else if (line.trim() === '---' || line.trim() === '***') {
        blocks.push({type:'hr'});
      } else if (line.trim() === '') {
        if (current.length) { blocks.push({type:'p', content:inline(current.join(' '))}); current = []; }
      } else { current.push(line.trim()); }
    }
    if (current.length) blocks.push({type:'p', content:inline(current.join(' '))});
    // Merge consecutive li
    const merged = [];
    let listBuffer = [];
    for (const b of blocks) {
      if (b.type === 'li') { listBuffer.push(b); }
      else { if (listBuffer.length) { merged.push({type:'list', items:listBuffer}); listBuffer=[]; } merged.push(b); }
    }
    if (listBuffer.length) merged.push({type:'list', items:listBuffer});
    return merged.map(b => {
      switch(b.type) {
        case 'p': return `<p class="paragraph">${b.content}</p>`;
        case 'heading': return `<h${b.level} class="paragraph">${b.content}</h${b.level}>`;
        case 'quote': return `<blockquote class="paragraph">${b.content}</blockquote>`;
        case 'code': return `<pre class="paragraph"><code class="language-${escape(b.lang)}">${escape(b.content)}</code></pre>`;
        case 'list': return `<${b.items[0].ordered?'ol':'ul'} class="paragraph">${b.items.map(i=>`<li>${i.content}</li>`).join('')}</${b.items[0].ordered?'ol':'ul'}>`;
        case 'hr': return '<hr class="paragraph">';
      }
    }).join('');
  };
})();

